from lib import *
S = SS('w83')
steps = [
    step("HTTP 代理看到的明文请求。我写了一个最小的转发代理,客户端(requests)通过它访问 http://example.com/:客户端发给代理的请求行是 \"GET http://example.com/ HTTP/1.1\"——绝对形式(absolute-form,带完整 URL),而直连时是 \"GET / HTTP/1.1\"(origin-form,只有路径)。原因是代理需要知道该连哪台主机。代理收到的头部有 host、user-agent、accept-encoding、accept、connection;转发给源站时它去掉了 Proxy-* 头和原来的 Connection 头(改成 Connection: close),并加了 Via: 1.1 w83proxy。客户端最终拿到 200、577 字节。代理看得到完整 URL、全部头部(包括 Cookie、Authorization)和整个消息体——明文 HTTP 对代理完全透明。", t=tl(S(1)), mark=lidx(S(1), '客户端经代理发出的请求行', '代理收到的头部名字'), done=lidx(S(1), '直连时的请求行', '代理能看到什么'), kv=KV([['经代理的请求行', 'GET http://example.com/ HTTP/1.1(绝对形式)'], ['直连的请求行', 'GET / HTTP/1.1'], ['代理的改动', '去掉 Proxy-*,加 Via']], ['经代理的请求行'])),
    step("HTTPS 经代理:CONNECT 隧道。客户端先对代理发 \"CONNECT example.com:443 HTTP/1.1\",代理回 200 Connection Established,之后代理只在两个套接字之间搬字节:客户端→服务器 1751 字节,服务器→客户端 6544 字节,全是 TLS 密文。代理在转发的第一批字节里能看到 TLS ClientHello 里明文的 SNI = example.com(所以代理知道你访问哪个站点),但看不到 URL 路径、头部、Cookie 和消息体。客户端用的是 example.com 自己的证书,requests 成功且没有证书错误,说明 TLS 是客户端与源站端到端建立的,代理没有做中间人。", t=tl(S(2)), mark=lidx(S(2), '客户端发给代理的第一行', '代理在转发的第一批字节里看到'), done=lidx(S(2), '代理中转的字节', '客户端校验的证书'), b=bars([['客户端→服务器', 1751, '1751 字节'], ['服务器→客户端', 6544, '6544 字节']], 6544, mark=[], done=[0, 1]), kv=KV([['代理看到', 'CONNECT example.com:443、SNI、字节数'], ['代理看不到', 'URL 路径、头部、Cookie、消息体'], ['证书', '源站自己的,端到端']], ['代理看到'])),
    step("CONNECT 多花的时间。客户端↔代理这一段加每方向 50 ms 延迟(往返 100 ms),代理↔example.com 是真实网络。直连访问 https://example.com/:中位 525 ms;经代理:中位 1161 ms,多出 636 ms(样本里有 1889 ms 的慢点)。分阶段拆开(各 3 次取中位):直连——TCP 连到源站 157 ms、TLS 握手 188 ms、HTTP 请求到首字节 375 ms;经代理——连到代理 101 ms(正好一个 100 ms 往返)、CONNECT 往返 264 ms(= 100 ms 的往返 + 代理去连源站的 TCP 约 157 ms)、TLS 握手 362 ms(比直连多 174 ms)、HTTP 请求到首字节 472 ms(比直连多 97 ms,正好一个 100 ms 往返)。所以代理多出的是:每个原本一次往返的阶段,现在都得多穿过客户端↔代理这一段。TLS 握手阶段多了 174 ms 而不是 100 ms,多出的 74 ms 来源我没有查明。", t=tl(S(3)), mark=lidx(S(3), '经代理各阶段', '经代理多出 636 ms'), done=lidx(S(3), '直连各阶段', '直连:', '经代理(客户端'), b=bars([['直连 合计', 720, '720 ms'], ['经代理 合计', 1199, '1199 ms'], ['TLS 握手 直连', 188, '188'], ['TLS 握手 经代理', 362, '362']], 1199, mark=[1, 3], done=[0, 2]), kv=KV([['连到代理', '101 ms(1 个 RTT)'], ['CONNECT 往返', '264 ms'], ['TLS 握手', '362 ms(直连 188)'], ['HTTP 请求', '472 ms(直连 375)']], ['TLS 握手'])),
    step("代理的各种答复和客户端的反应。CONNECT 到被策略禁止的主机:代理返回 403;客户端抛 ProxyError(\"Unable to connect to proxy\")。CONNECT 到连不上的目标(127.0.0.1:9):代理返回 502;客户端同样是 ProxyError。要求认证的代理:不带凭据 → 407 Proxy Authentication Required,Proxy-Authenticate: Basic realm=\"w83\";带上凭据后(代理地址里写 user:pass)→ 200;代理收到的 Proxy-Authorization 是 \"Basic dXNlcjpwYXNz\",base64 解码就是 user:pass——Basic 只是编码不是加密,所以代理认证如果走明文连接,凭据等于裸奔。", t=tl(S(4)), mark=lidx(S(4), '代理要求认证', '带上凭据'), done=lidx(S(4), 'CONNECT 到被禁止的主机', 'CONNECT 到连不上的目标'), kv=KV([['403', '策略禁止 → 客户端 ProxyError'], ['502', '代理连不上目标 → 客户端 ProxyError'], ['407', 'Proxy-Authenticate: Basic …'], ['Basic 凭据', 'base64 编码,不是加密']], ['407'])),
]
A = mkartw('w83', 83, '网络协议,HTTP,代理,CONNECT,隧道,SNI,407,真实验证,动画演示',
    '用自己写的最小代理实测 HTTP 代理:明文请求行变成绝对形式,代理能看到全部内容;HTTPS 走 CONNECT 隧道,代理只看得到 CONNECT 目标和 SNI、1751 / 6544 字节密文;客户端↔代理 100 ms 往返时 HTTPS 访问从 525 ms 增到 1161 ms(连到代理 101、CONNECT 264、TLS 362、HTTP 472 ms);403 / 502 / 407 的反应。',
    '企业网络、翻墙工具、抓包软件都离不开 HTTP 代理。明文 HTTP 经代理时请求行有什么不同?HTTPS 为什么要 CONNECT?代理到底能看到什么、不能看到什么?代理多花了几个往返?这篇自己写了一个最小代理,在本机把这些问题逐个量出来。',
    [('SNI = example.com', 'CONNECT 隧道里代理能从第一批字节读到的唯一明文信息(除 CONNECT 目标外)'), ('525 → 1161 ms', '客户端↔代理 100 ms 往返时,直连与经代理访问 https://example.com/ 的耗时中位数'), ('Basic dXNlcjpwYXNz', '代理认证里 base64 编码的凭据(解码即 user:pass)')],
    [('明文 HTTP', '<p>请求行用绝对形式带完整 URL;代理看得到一切并可以修改头部。</p>'),
     ('CONNECT 隧道', '<p>代理回 200 之后只搬字节;TLS 是端到端的,代理看到 CONNECT 目标和 SNI,看不到 URL 与内容。</p>'),
     ('额外延迟', '<p>每个原本的往返现在都多穿过一段客户端↔代理;连到代理 1 个 RTT,CONNECT 再 1 个 RTT。</p>'),
     ('失败与认证', '<p>403 / 502 对客户端都是 ProxyError;407 要求 Proxy-Authorization,Basic 只是 base64。</p>')],
    steps,
    [ENV_W + '。代理是我写的最小转发代理(线程 + 套接字搬字节,监听 lo0 的 9400~9499 端口),不是任何现成软件;HTTPS 目标是真实的 example.com:443,延迟用 netlab 只作用在客户端↔代理这一段;分阶段计时每种只测 3 次',
     '没有验证:MITM 代理(自签 CA 解密 HTTPS)的行为;HTTP/2 over CONNECT;SOCKS 代理;代理自动配置(PAC / WPAD);HTTPS 代理(客户端到代理本身再加密);TLS 阶段多出 74 ms 的原因;浏览器对代理的行为'],
    '代理与 CONNECT')
